import torch
from torch.autograd import Function
from torch.nn import Module
import triton
import triton.language as tl

@triton.jit
def frobenius_norm_kernel(X_ptr, N, C, stride0, stride1, output_ptr, block_size: int = 32):
    pid = triton.program_id(0)
    num_blocks = (N * C + block_size - 1) // block_size
    start = pid * block_size
    end = min(start + block_size, N * C)
    sum = 0.0
    for i in range(start, end):
        sum += X_ptr[i] * X_ptr[i]
    output_ptr[pid] = sum

class FrobeniusNorm(Function):
    @staticmethod
    def forward(ctx, input):
        N, C = input.shape
        output = torch.zeros(1, device=input.device)
        frobenius_norm_kernel[triton.cdiv(N * C, 32), 32](input.view(-1).contiguous(), N, C, 1, C, output.view(-1).contiguous())
        ctx.save_for_backward(input)
        return torch.sqrt(output[0])

    @staticmethod
    def backward(ctx, grad_output):
        input, = ctx.saved_tensors
        norm = torch.norm(input, p='fro')
        grad_input = grad_output * input / norm
        return grad_input

